/* GAMBASKET CANONICAL AFFILIATE ENGINE — visitor_token based. Run as one script. */
begin;

drop table if exists public.affiliate_payout_allocations cascade;
drop table if exists public.affiliate_payout_requests cascade;
drop table if exists public.affiliate_conversions cascade;
drop table if exists public.affiliate_attributions cascade;
drop table if exists public.affiliate_clicks cascade;
drop table if exists public.affiliate_links cascade;
drop table if exists public.affiliate_profiles cascade;
drop table if exists public.affiliate_settings cascade;
drop function if exists public.record_affiliate_click(varchar, uuid, uuid, varchar, text);
drop function if exists public.record_affiliate_click(varchar, uuid, text, uuid, text);
drop function if exists public.record_affiliate_conversion(uuid, varchar, varchar);
drop function if exists public.record_affiliate_conversion(uuid, text);
drop function if exists public.get_affiliate_attribution(varchar);
drop function if exists public.get_current_affiliate_attribution(text);
drop function if exists public.get_or_create_affiliate();
drop function if exists public.get_or_create_affiliate_profile();
drop function if exists public.create_affiliate_link(uuid);
drop function if exists public.get_my_affiliate_links();
drop function if exists public.get_affiliate_dashboard();
drop function if exists public.request_affiliate_payout(numeric, varchar, varchar);
drop function if exists public.attach_affiliate_attribution(text);
drop function if exists public.affiliate_try_conversion(uuid, uuid);
drop trigger if exists affiliate_conversion_on_paid_order on public.orders;
drop function if exists public.affiliate_conversion_on_paid_order();
drop function if exists public.is_affiliate_admin();
drop function if exists public.touch_affiliate_updated_at();
drop function if exists public.generate_affiliate_code();
drop function if exists public.admin_affiliate_overview();
drop function if exists public.admin_get_affiliate_settings();
drop function if exists public.admin_list_affiliates(text, varchar);
drop function if exists public.admin_get_affiliate_detail(uuid);
drop function if exists public.admin_list_affiliate_conversions(varchar);
drop function if exists public.admin_list_affiliate_payouts(varchar);
drop function if exists public.admin_list_affiliate_traffic(integer);
drop function if exists public.admin_update_affiliate(uuid, varchar, numeric);
drop function if exists public.admin_approve_commission(uuid);
drop function if exists public.admin_reject_commission(uuid, text);
drop function if exists public.admin_approve_affiliate_payout(uuid, text);
drop function if exists public.admin_reject_affiliate_payout(uuid, text);
drop function if exists public.admin_mark_affiliate_payout_paid(uuid);
drop function if exists public.admin_update_affiliate_settings(boolean, numeric, numeric, integer);

create extension if not exists pgcrypto;
create table public.affiliate_settings (id boolean primary key default true check(id), enabled boolean not null default true, default_commission_rate numeric(8,2) not null default 5 check(default_commission_rate between 0 and 100), minimum_payout numeric(14,2) not null default 100 check(minimum_payout >= 0), attribution_days integer not null default 30 check(attribution_days between 1 and 365), updated_at timestamptz not null default now());
insert into public.affiliate_settings(id) values(true);
create table public.affiliate_profiles (id uuid primary key default gen_random_uuid(), user_id uuid not null unique references public.profiles(id) on delete cascade, affiliate_code varchar(40) not null unique, display_name varchar(120), status varchar(20) not null default 'active' check(status in ('active','suspended','disabled')), commission_rate numeric(8,2) check(commission_rate between 0 and 100), total_clicks bigint not null default 0, total_orders bigint not null default 0, total_sales numeric(14,2) not null default 0, total_commission numeric(14,2) not null default 0, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.affiliate_links (id uuid primary key default gen_random_uuid(), affiliate_id uuid not null references public.affiliate_profiles(id) on delete cascade, product_id uuid not null references public.products(id) on delete cascade, clicks bigint not null default 0, created_at timestamptz not null default now(), last_clicked_at timestamptz, unique(affiliate_id,product_id));
create table public.affiliate_clicks (id uuid primary key default gen_random_uuid(), affiliate_id uuid not null references public.affiliate_profiles(id) on delete cascade, affiliate_link_id uuid references public.affiliate_links(id) on delete set null, product_id uuid references public.products(id) on delete set null, visitor_token text not null, user_id uuid references public.profiles(id) on delete set null, landing_page text, created_at timestamptz not null default now());
create table public.affiliate_attributions (id uuid primary key default gen_random_uuid(), visitor_token text not null unique, user_id uuid references public.profiles(id) on delete set null, affiliate_id uuid not null references public.affiliate_profiles(id) on delete cascade, affiliate_link_id uuid references public.affiliate_links(id) on delete set null, product_id uuid references public.products(id) on delete set null, expires_at timestamptz not null, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.affiliate_conversions (id uuid primary key default gen_random_uuid(), affiliate_id uuid not null references public.affiliate_profiles(id) on delete restrict, affiliate_link_id uuid references public.affiliate_links(id) on delete set null, order_id uuid not null unique references public.orders(id) on delete restrict, buyer_id uuid references public.profiles(id) on delete set null, sale_amount numeric(14,2) not null, commission_rate numeric(8,2) not null, commission_amount numeric(14,2) not null, status varchar(20) not null default 'pending' check(status in ('pending','approved','rejected','paid')), rejection_reason text, created_at timestamptz not null default now(), approved_at timestamptz, paid_at timestamptz);
create table public.affiliate_payout_requests (id uuid primary key default gen_random_uuid(), affiliate_id uuid not null references public.affiliate_profiles(id) on delete restrict, amount numeric(14,2) not null check(amount > 0), payment_method varchar(50) not null, payment_account varchar(120) not null, status varchar(20) not null default 'pending' check(status in ('pending','approved','rejected','paid')), admin_notes text, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), paid_at timestamptz);
create table public.affiliate_payout_allocations (id uuid primary key default gen_random_uuid(), payout_id uuid not null references public.affiliate_payout_requests(id) on delete cascade, conversion_id uuid not null references public.affiliate_conversions(id) on delete restrict, amount numeric(14,2) not null check(amount > 0), created_at timestamptz not null default now(), unique(payout_id,conversion_id));
create index affiliate_clicks_token_idx on public.affiliate_clicks(visitor_token); create index affiliate_attributions_user_idx on public.affiliate_attributions(user_id); create index affiliate_conversions_affiliate_idx on public.affiliate_conversions(affiliate_id); create index affiliate_payouts_affiliate_idx on public.affiliate_payout_requests(affiliate_id);

create function public.is_affiliate_admin() returns boolean language sql security definer stable set search_path=public as $$select exists(select 1 from public.user_roles where user_id=auth.uid() and role_id='admin' and is_active=true)$$;
create function public.touch_affiliate_updated_at() returns trigger language plpgsql security definer set search_path=public as $$begin new.updated_at=now(); return new; end$$;
create trigger affiliate_profiles_touch before update on public.affiliate_profiles for each row execute function public.touch_affiliate_updated_at();
create trigger affiliate_settings_touch before update on public.affiliate_settings for each row execute function public.touch_affiliate_updated_at();
create trigger affiliate_payouts_touch before update on public.affiliate_payout_requests for each row execute function public.touch_affiliate_updated_at();
create function public.generate_affiliate_code() returns varchar language plpgsql security definer set search_path=public as $$declare c varchar; begin loop c:='GB'||upper(substring(replace(gen_random_uuid()::text,'-','') from 1 for 8)); exit when not exists(select 1 from public.affiliate_profiles where affiliate_code=c); end loop; return c; end$$;
create function public.get_or_create_affiliate_profile() returns public.affiliate_profiles language plpgsql security definer set search_path=public as $$declare r public.affiliate_profiles; begin if auth.uid() is null then raise exception 'Authentication required'; end if; select * into r from public.affiliate_profiles where user_id=auth.uid(); if found then return r; end if; insert into public.affiliate_profiles(user_id,affiliate_code,display_name) values(auth.uid(),public.generate_affiliate_code(),'GamBasket Affiliate') returning * into r; return r; end$$;
create function public.get_or_create_affiliate() returns public.affiliate_profiles language sql security definer set search_path=public as $$select * from public.get_or_create_affiliate_profile()$$;
create function public.create_affiliate_link(p_product_id uuid) returns public.affiliate_links language plpgsql security definer set search_path=public as $$declare a public.affiliate_profiles; r public.affiliate_links; begin select * into a from public.get_or_create_affiliate_profile(); if a.status<>'active' then raise exception 'Affiliate account is not active'; end if; if not exists(select 1 from public.products where id=p_product_id and status='approved') then raise exception 'Product is not available for promotion'; end if; insert into public.affiliate_links(affiliate_id,product_id) values(a.id,p_product_id) on conflict(affiliate_id,product_id) do update set last_clicked_at=public.affiliate_links.last_clicked_at returning * into r; return r; end$$;
create function public.record_affiliate_click(p_affiliate_code varchar,p_product_id uuid,p_visitor_token text,p_link_id uuid default null,p_landing_page text default null) returns jsonb language plpgsql security definer set search_path=public as $$declare a public.affiliate_profiles; l public.affiliate_links; expiry timestamptz; begin if p_visitor_token is null or length(trim(p_visitor_token))<8 then raise exception 'Visitor token required'; end if; if not exists(select 1 from public.affiliate_settings where id and enabled) then return jsonb_build_object('success',false); end if; select * into a from public.affiliate_profiles where affiliate_code=upper(trim(p_affiliate_code)) and status='active'; if not found then return jsonb_build_object('success',false); end if; if p_link_id is not null then select * into l from public.affiliate_links where id=p_link_id and affiliate_id=a.id; if not found or (p_product_id is not null and l.product_id<>p_product_id) then raise exception 'Invalid affiliate link'; end if; p_product_id:=l.product_id; end if; select now()+make_interval(days=>attribution_days) into expiry from public.affiliate_settings where id; insert into public.affiliate_clicks(affiliate_id,affiliate_link_id,product_id,visitor_token,user_id,landing_page) values(a.id,p_link_id,p_product_id,p_visitor_token,auth.uid(),left(p_landing_page,2000)); update public.affiliate_profiles set total_clicks=total_clicks+1 where id=a.id; if p_link_id is not null then update public.affiliate_links set clicks=clicks+1,last_clicked_at=now() where id=p_link_id; end if; insert into public.affiliate_attributions(visitor_token,user_id,affiliate_id,affiliate_link_id,product_id,expires_at) values(p_visitor_token,auth.uid(),a.id,p_link_id,p_product_id,expiry) on conflict(visitor_token) do update set user_id=coalesce(excluded.user_id,public.affiliate_attributions.user_id),affiliate_id=excluded.affiliate_id,affiliate_link_id=excluded.affiliate_link_id,product_id=excluded.product_id,expires_at=excluded.expires_at,updated_at=now(); return jsonb_build_object('success',true,'expires_at',expiry); end$$;
create function public.attach_affiliate_attribution(p_visitor_token text) returns boolean language plpgsql security definer set search_path=public as $$begin if auth.uid() is null then return false; end if; update public.affiliate_attributions set user_id=auth.uid(),updated_at=now() where visitor_token=p_visitor_token and expires_at>now(); return found; end$$;
create function public.get_current_affiliate_attribution(p_visitor_token text default null) returns jsonb language sql security definer stable set search_path=public as $$select jsonb_build_object('affiliate_id',a.affiliate_id,'affiliate_link_id',a.affiliate_link_id,'product_id',a.product_id,'expires_at',a.expires_at) from public.affiliate_attributions a where a.expires_at>now() and ((auth.uid() is not null and a.user_id=auth.uid()) or (p_visitor_token is not null and a.visitor_token=p_visitor_token)) order by a.updated_at desc limit 1$$;

create function public.affiliate_try_conversion(p_order_id uuid,p_buyer_id uuid) returns public.affiliate_conversions language plpgsql security definer set search_path=public as $$declare o public.orders; a public.affiliate_attributions; p public.affiliate_profiles; rate numeric; r public.affiliate_conversions; begin select * into r from public.affiliate_conversions where order_id=p_order_id; if found then return r; end if; select * into o from public.orders where id=p_order_id and buyer_id=p_buyer_id; if not found or lower(coalesce(o.payment_status,'')) not in ('paid','completed','success','successful') or lower(coalesce(o.order_status,'')) in ('cancelled','canceled','refunded') then return null; end if; select * into a from public.affiliate_attributions where user_id=p_buyer_id and expires_at>now() order by updated_at desc limit 1; if not found then return null; end if; select * into p from public.affiliate_profiles where id=a.affiliate_id and status='active'; if not found or p.user_id=p_buyer_id then return null; end if; select coalesce(p.commission_rate,s.default_commission_rate) into rate from public.affiliate_settings s where id; insert into public.affiliate_conversions(affiliate_id,affiliate_link_id,order_id,buyer_id,sale_amount,commission_rate,commission_amount) values(p.id,a.affiliate_link_id,o.id,p_buyer_id,o.subtotal,rate,round(o.subtotal*rate/100,2)) returning * into r; update public.affiliate_profiles set total_orders=total_orders+1,total_sales=total_sales+o.subtotal,total_commission=total_commission+r.commission_amount where id=p.id; return r; end$$;
create function public.record_affiliate_conversion(p_order_id uuid,p_visitor_token text default null) returns public.affiliate_conversions language plpgsql security definer set search_path=public as $$declare r public.affiliate_conversions; begin if auth.uid() is null then raise exception 'Authentication required'; end if; perform public.attach_affiliate_attribution(p_visitor_token); select * into r from public.affiliate_try_conversion(p_order_id,auth.uid()); if r.id is null then raise exception 'No eligible paid affiliate order found'; end if; return r; end$$;
create function public.affiliate_conversion_on_paid_order() returns trigger language plpgsql security definer set search_path=public as $$begin if lower(coalesce(new.payment_status,'')) in ('paid','completed','success','successful') then perform public.affiliate_try_conversion(new.id,new.buyer_id); end if; return new; end$$;
create trigger affiliate_conversion_on_paid_order after insert or update of payment_status on public.orders for each row execute function public.affiliate_conversion_on_paid_order();
create function public.get_my_affiliate_links() returns table(id uuid,product_id uuid,clicks bigint,created_at timestamptz,last_clicked_at timestamptz,product_title varchar,price numeric,currency varchar,main_image text) language sql security definer stable set search_path=public as $$select l.id,l.product_id,l.clicks,l.created_at,l.last_clicked_at,p.title,p.price,p.currency,p.main_image from public.affiliate_links l join public.affiliate_profiles a on a.id=l.affiliate_id left join public.products p on p.id=l.product_id where a.user_id=auth.uid() order by l.created_at desc$$;
create function public.get_affiliate_dashboard() returns jsonb language plpgsql security definer set search_path=public as $$declare a public.affiliate_profiles; begin select * into a from public.get_or_create_affiliate_profile(); return jsonb_build_object('profile',to_jsonb(a),'clicks',a.total_clicks,'orders',a.total_orders,'sales',a.total_sales,'commission',a.total_commission,'pending_balance',(select coalesce(sum(commission_amount),0) from public.affiliate_conversions where affiliate_id=a.id and status='pending'),'approved_balance',(select coalesce(sum(commission_amount),0) from public.affiliate_conversions where affiliate_id=a.id and status='approved'),'paid_balance',(select coalesce(sum(commission_amount),0) from public.affiliate_conversions where affiliate_id=a.id and status='paid')); end$$;
create function public.request_affiliate_payout(p_amount numeric,p_payment_method varchar,p_payment_account varchar) returns public.affiliate_payout_requests language plpgsql security definer set search_path=public as $$declare a public.affiliate_profiles; available numeric; r public.affiliate_payout_requests; remaining numeric; x record; taken numeric; begin select * into a from public.affiliate_profiles where user_id=auth.uid() and status='active'; if not found then raise exception 'Active affiliate account required'; end if; if p_amount<(select minimum_payout from public.affiliate_settings where id) then raise exception 'Minimum payout not met'; end if; select coalesce(sum(c.commission_amount-coalesce(z.reserved,0)),0) into available from public.affiliate_conversions c left join lateral(select sum(i.amount) reserved from public.affiliate_payout_allocations i join public.affiliate_payout_requests q on q.id=i.payout_id where i.conversion_id=c.id and q.status in ('pending','approved','paid'))z on true where c.affiliate_id=a.id and c.status='approved'; if p_amount>available then raise exception 'Requested payout exceeds available approved commission'; end if; insert into public.affiliate_payout_requests(affiliate_id,amount,payment_method,payment_account) values(a.id,p_amount,p_payment_method,p_payment_account) returning * into r; remaining:=p_amount; for x in select c.id,c.commission_amount-coalesce(z.reserved,0) available from public.affiliate_conversions c left join lateral(select sum(i.amount) reserved from public.affiliate_payout_allocations i join public.affiliate_payout_requests q on q.id=i.payout_id where i.conversion_id=c.id and q.status in ('pending','approved','paid'))z on true where c.affiliate_id=a.id and c.status='approved' order by c.approved_at,c.created_at loop exit when remaining<=0; taken:=least(remaining,x.available); insert into public.affiliate_payout_allocations(payout_id,conversion_id,amount) values(r.id,x.id,taken); remaining:=remaining-taken; end loop; return r; end$$;

-- Admin RPC API consumed by js/admin-affiliate.js.
create function public.admin_affiliate_overview() returns jsonb language plpgsql security definer set search_path=public as $$begin if not public.is_affiliate_admin() then raise exception 'Admin access required'; end if; return jsonb_build_object('affiliates',(select count(*) from public.affiliate_profiles),'clicks',(select coalesce(sum(total_clicks),0) from public.affiliate_profiles),'conversions',(select count(*) from public.affiliate_conversions),'sales',(select coalesce(sum(sale_amount),0) from public.affiliate_conversions where status<>'rejected'),'pending_commission',(select coalesce(sum(commission_amount),0) from public.affiliate_conversions where status='pending'),'approved_commission',(select coalesce(sum(commission_amount),0) from public.affiliate_conversions where status='approved')); end$$;
create function public.admin_get_affiliate_settings() returns public.affiliate_settings language plpgsql security definer set search_path=public as $$declare r public.affiliate_settings; begin if not public.is_affiliate_admin() then raise exception 'Admin access required'; end if; select * into r from public.affiliate_settings where id; return r; end$$;
create function public.admin_list_affiliates(p_search text default null,p_status varchar default null) returns table(id uuid,user_id uuid,affiliate_code varchar,display_name varchar,status varchar,commission_rate numeric,total_clicks bigint,total_orders bigint,total_sales numeric,total_commission numeric,email varchar,phone varchar,created_at timestamptz) language sql security definer stable set search_path=public as $$select a.id,a.user_id,a.affiliate_code,a.display_name,a.status,coalesce(a.commission_rate,s.default_commission_rate),a.total_clicks,a.total_orders,a.total_sales,a.total_commission,p.email,p.phone,a.created_at from public.affiliate_profiles a join public.profiles p on p.id=a.user_id cross join public.affiliate_settings s where public.is_affiliate_admin() and (p_status is null or p_status='' or a.status=p_status) and (p_search is null or p_search='' or concat_ws(' ',a.affiliate_code,a.display_name,p.email,p.phone) ilike '%'||p_search||'%') order by a.created_at desc$$;
create function public.admin_get_affiliate_detail(p_affiliate_id uuid) returns jsonb language plpgsql security definer set search_path=public as $$begin if not public.is_affiliate_admin() then raise exception 'Admin access required'; end if; return jsonb_build_object('affiliate',(select to_jsonb(x) from(select a.*,p.first_name,p.last_name,p.email,p.phone,p.region,p.area from public.affiliate_profiles a join public.profiles p on p.id=a.user_id where a.id=p_affiliate_id)x),'links',(select coalesce(jsonb_agg(to_jsonb(x)),'[]')from(select l.*,p.title,p.price from public.affiliate_links l left join public.products p on p.id=l.product_id where l.affiliate_id=p_affiliate_id order by l.clicks desc)x),'conversions',(select coalesce(jsonb_agg(to_jsonb(x)),'[]')from(select c.*,o.order_number,o.currency from public.affiliate_conversions c left join public.orders o on o.id=c.order_id where c.affiliate_id=p_affiliate_id order by c.created_at desc limit 50)x)); end$$;
create function public.admin_list_affiliate_conversions(p_status varchar default null) returns table(id uuid,affiliate_id uuid,affiliate_code varchar,affiliate_name varchar,order_id uuid,order_number varchar,buyer_email varchar,sale_amount numeric,commission_amount numeric,commission_rate numeric,status varchar,created_at timestamptz) language sql security definer stable set search_path=public as $$select c.id,c.affiliate_id,a.affiliate_code,coalesce(a.display_name,p.email),c.order_id,o.order_number,b.email,c.sale_amount,c.commission_amount,c.commission_rate,c.status,c.created_at from public.affiliate_conversions c join public.affiliate_profiles a on a.id=c.affiliate_id join public.profiles p on p.id=a.user_id left join public.orders o on o.id=c.order_id left join public.profiles b on b.id=c.buyer_id where public.is_affiliate_admin() and (p_status is null or p_status='' or c.status=p_status) order by c.created_at desc$$;
create function public.admin_list_affiliate_payouts(p_status varchar default null) returns table(id uuid,affiliate_id uuid,affiliate_code varchar,affiliate_name varchar,amount numeric,payment_method varchar,payment_account varchar,status varchar,admin_notes text,created_at timestamptz,paid_at timestamptz) language sql security definer stable set search_path=public as $$select r.id,r.affiliate_id,a.affiliate_code,coalesce(a.display_name,p.email),r.amount,r.payment_method,r.payment_account,r.status,r.admin_notes,r.created_at,r.paid_at from public.affiliate_payout_requests r join public.affiliate_profiles a on a.id=r.affiliate_id join public.profiles p on p.id=a.user_id where public.is_affiliate_admin() and(p_status is null or p_status='' or r.status=p_status) order by r.created_at desc$$;
create function public.admin_list_affiliate_traffic(p_limit integer default 100) returns table(id uuid,affiliate_code varchar,affiliate_name varchar,product_title varchar,visitor_token text,landing_page text,created_at timestamptz) language sql security definer stable set search_path=public as $$select c.id,a.affiliate_code,coalesce(a.display_name,p.email),pr.title,c.visitor_token,c.landing_page,c.created_at from public.affiliate_clicks c join public.affiliate_profiles a on a.id=c.affiliate_id join public.profiles p on p.id=a.user_id left join public.products pr on pr.id=c.product_id where public.is_affiliate_admin() order by c.created_at desc limit least(greatest(coalesce(p_limit,100),1),500)$$;
create function public.admin_update_affiliate(p_affiliate_id uuid,p_status varchar default null,p_commission_rate numeric default null) returns public.affiliate_profiles language plpgsql security definer set search_path=public as $$declare r public.affiliate_profiles; begin if not public.is_affiliate_admin() then raise exception 'Admin access required'; end if; update public.affiliate_profiles set status=coalesce(p_status,status),commission_rate=coalesce(p_commission_rate,commission_rate) where id=p_affiliate_id returning * into r; if r.id is null then raise exception 'Affiliate not found'; end if; return r; end$$;
create function public.admin_approve_commission(p_conversion_id uuid) returns public.affiliate_conversions language plpgsql security definer set search_path=public as $$declare r public.affiliate_conversions; begin if not public.is_affiliate_admin() then raise exception 'Admin access required'; end if; update public.affiliate_conversions set status='approved',approved_at=now(),rejection_reason=null where id=p_conversion_id and status='pending' returning * into r; if r.id is null then raise exception 'Only pending commissions can be approved'; end if; return r; end$$;
create function public.admin_reject_commission(p_conversion_id uuid,p_reason text) returns public.affiliate_conversions language plpgsql security definer set search_path=public as $$declare r public.affiliate_conversions; begin if not public.is_affiliate_admin() then raise exception 'Admin access required'; end if; update public.affiliate_conversions set status='rejected',rejection_reason=p_reason where id=p_conversion_id and status='pending' returning * into r; if r.id is null then raise exception 'Only pending commissions can be rejected'; end if; return r; end$$;
create function public.admin_approve_affiliate_payout(p_payout_id uuid,p_notes text default null) returns public.affiliate_payout_requests language plpgsql security definer set search_path=public as $$declare r public.affiliate_payout_requests; begin if not public.is_affiliate_admin() then raise exception 'Admin access required'; end if; update public.affiliate_payout_requests set status='approved',admin_notes=p_notes where id=p_payout_id and status='pending' returning * into r; if r.id is null then raise exception 'Only pending payouts can be approved'; end if; return r; end$$;
create function public.admin_reject_affiliate_payout(p_payout_id uuid,p_reason text) returns public.affiliate_payout_requests language plpgsql security definer set search_path=public as $$declare r public.affiliate_payout_requests; begin if not public.is_affiliate_admin() then raise exception 'Admin access required'; end if; update public.affiliate_payout_requests set status='rejected',admin_notes=p_reason where id=p_payout_id and status in('pending','approved') returning * into r; if r.id is null then raise exception 'Payout cannot be rejected'; end if; delete from public.affiliate_payout_allocations where payout_id=p_payout_id; return r; end$$;
create function public.admin_mark_affiliate_payout_paid(p_payout_id uuid) returns public.affiliate_payout_requests language plpgsql security definer set search_path=public as $$declare r public.affiliate_payout_requests; begin if not public.is_affiliate_admin() then raise exception 'Admin access required'; end if; update public.affiliate_payout_requests set status='paid',paid_at=now() where id=p_payout_id and status='approved' returning * into r; if r.id is null then raise exception 'Only approved payouts can be paid'; end if; update public.affiliate_conversions c set status='paid',paid_at=now() where c.status='approved' and c.commission_amount<=(select coalesce(sum(i.amount),0) from public.affiliate_payout_allocations i join public.affiliate_payout_requests p on p.id=i.payout_id where i.conversion_id=c.id and p.status='paid'); return r; end$$;
create function public.admin_update_affiliate_settings(p_enabled boolean,p_default_commission_rate numeric,p_minimum_payout numeric,p_attribution_days integer) returns public.affiliate_settings language plpgsql security definer set search_path=public as $$declare r public.affiliate_settings; begin if not public.is_affiliate_admin() then raise exception 'Admin access required'; end if; update public.affiliate_settings set enabled=p_enabled,default_commission_rate=p_default_commission_rate,minimum_payout=p_minimum_payout,attribution_days=p_attribution_days where id returning * into r; return r; end$$;

alter table public.affiliate_settings enable row level security; alter table public.affiliate_profiles enable row level security; alter table public.affiliate_links enable row level security; alter table public.affiliate_clicks enable row level security; alter table public.affiliate_attributions enable row level security; alter table public.affiliate_conversions enable row level security; alter table public.affiliate_payout_requests enable row level security; alter table public.affiliate_payout_allocations enable row level security;
create policy affiliate_profiles_own on public.affiliate_profiles for select to authenticated using(user_id=auth.uid()); create policy affiliate_links_own on public.affiliate_links for select to authenticated using(affiliate_id in(select id from public.affiliate_profiles where user_id=auth.uid())); create policy affiliate_conversions_own on public.affiliate_conversions for select to authenticated using(affiliate_id in(select id from public.affiliate_profiles where user_id=auth.uid())); create policy affiliate_payouts_own on public.affiliate_payout_requests for select to authenticated using(affiliate_id in(select id from public.affiliate_profiles where user_id=auth.uid()));
grant select on public.affiliate_profiles,public.affiliate_links,public.affiliate_conversions,public.affiliate_payout_requests to authenticated;
grant execute on function public.get_or_create_affiliate_profile(),public.get_or_create_affiliate(),public.create_affiliate_link(uuid),public.get_my_affiliate_links(),public.get_affiliate_dashboard(),public.attach_affiliate_attribution(text),public.record_affiliate_conversion(uuid,text),public.request_affiliate_payout(numeric,varchar,varchar) to authenticated;
grant execute on function public.record_affiliate_click(varchar,uuid,text,uuid,text),public.get_current_affiliate_attribution(text) to anon,authenticated;
grant execute on function public.is_affiliate_admin(),public.admin_affiliate_overview(),public.admin_get_affiliate_settings(),public.admin_list_affiliates(text,varchar),public.admin_get_affiliate_detail(uuid),public.admin_list_affiliate_conversions(varchar),public.admin_list_affiliate_payouts(varchar),public.admin_list_affiliate_traffic(integer),public.admin_update_affiliate(uuid,varchar,numeric),public.admin_approve_commission(uuid),public.admin_reject_commission(uuid,text),public.admin_approve_affiliate_payout(uuid,text),public.admin_reject_affiliate_payout(uuid,text),public.admin_mark_affiliate_payout_paid(uuid),public.admin_update_affiliate_settings(boolean,numeric,numeric,integer) to authenticated;
commit;
